-- =====================================================================
--  609_skrs_kod_listeleri.sql
--  KOD LİSTELERİ ARTIK SKRS'NİN KENDİSİ.
--
--  Bugüne kadar HBYS kod listeleri elle yazılmıştı ve e-Nabız'a gönderim
--  sırasında `enabiz_kod_esleme` tablosuyla SKRS'ye çevriliyordu. Çeviri
--  katmanı iki hataya açıktı: eşlenmemiş değer sessizce boş gidiyor,
--  elle yazılmış ad SKRS'deki addan ayrışıyordu - çıkış şekli 1 yerelde
--  "Şifa ile", SKRS'de "TEDAVİ ÖNERİLERİYLE ÇIKIŞ".
--
--  Bu göç listeleri SKRS Web Servisi'nden (GetSkrsObject) çekilmiş
--  gerçek içerikle değiştirir: deger = SKRS KODU, ad = SKRS ADI,
--  aktif = SKRS AKTIF. Böylece çeviriye gerek kalmaz - yerel kodun
--  KENDİSİ SKRS kodudur.
--
--  Kaynak: https://skrs.saglik.gov.tr/api/SkrsService/GetSkrsObject
--  Çekim: 12.09.2026
--
--  SKRS'de PASİF olan değerler SİLİNMEZ, aktif = 0 ile durur: eski
--  kayıtlar o kodu taşıyor olabilir, listeden düşmek geçmişi okunamaz
--  yapardı.
-- =====================================================================


-- --------------------------------------------------------------------
--  hasta.cinsiyet  <-  SKRS "CİNSİYET"  (4 değer)
-- --------------------------------------------------------------------
insert into public.kod_liste (kod, ad, skrs_liste) values
       ('hasta.cinsiyet', 'Cinsiyet (SKRS)', '784d0f4f-0603-4425-937f-1a3941fc3a1f')
on conflict (kod) do update set ad = excluded.ad,
                                skrs_liste = excluded.skrs_liste;

with v(deger, ad, aktif) as (values
      (1, 'ERKEK'::varchar, 1::smallint)
    , (2, 'KADIN', 1)
    , (3, 'HER İKİ CİNSİYET/BELİRSİZ', 0)
    , (9, 'BELİRTİLMEDİ', 0)
)
insert into public.kod_deger (liste_id, deger, dil, ad, sira, aktif, skrs_kod)
select l.id, v.deger, 0, v.ad, least(v.deger, 32000)::smallint, v.aktif, v.deger::varchar
  from v cross join public.kod_liste l
 where l.kod = 'hasta.cinsiyet'
on conflict (liste_id, deger, dil) do update
   set ad       = excluded.ad,
       aktif    = excluded.aktif,
       skrs_kod = excluded.skrs_kod;

