insert into public.kod_deger (liste_id, deger, dil, ad, sira, aktif, skrs_kod)
select l.id, v.deger, 0, v.ad, least(v.deger, 32000)::smallint, v.aktif, v.deger::varchar
  from v cross join public.kod_liste l
 where l.kod = 'taraf.meslek'
on conflict (liste_id, deger, dil) do update
   set ad       = excluded.ad,
       aktif    = excluded.aktif,
       skrs_kod = excluded.skrs_kod;

-- --------------------------------------------------------------------
--  SKRS'de KARŞILIĞI OLMAYAN YEREL DEĞERLER
-- --------------------------------------------------------------------
-- Medeni hal 4 "Eşi Ölmüş" SKRS'de ayrı kod değil, SKRS 3'ün
-- (BOŞANMIŞ / DUL / AYRI YAŞIYOR) içinde. Değer yerelde KALIR - hasta
-- kartında anlamlı bir ayrım - ama e-Nabız'a 3 olarak gider.
update public.kod_deger d
   set skrs_kod = '3'
  from public.kod_liste l
 where l.id = d.liste_id and l.kod = 'hasta.medeni_hal' and d.deger = 4;

-- Reçete türü yerelde 0 tabanlı (0=Normal), SKRS'de 1 tabanlı. Değerler
-- ilaç kayıtlarında kullanımda olduğu için DEĞİŞMEZ; yalnız liste
-- SKRS'ye bağlanır (skrs_kod eşlemesi zaten dolu).
update public.kod_liste
   set skrs_liste = 'c2fbe9bb-f6b3-4cb5-8670-47890ed7ed4b'
 where kod = 'ilac.recete_turu';

-- --------------------------------------------------------------------
--  UYRUK: 'TR' / 'TC'  ->  MERNİS 9980
-- --------------------------------------------------------------------
-- USS uyruk alanında ISO harf kodunu (TR) reddediyor, MERNİS kodunu
-- (9980) istiyor: canlı denemede code="TR" -> "E1008 Code 'TR' ve value
-- '...' degerleriyle Guid '...' bulunamadi"; code="9980" ile alan kabul
-- edildi. Yerel alan artık MERNİS kodunu tutar.

-- NOT: taraf_hasta'da NOT VALID bir dogum-tarihi kisiti var; goc oncesi
-- girilmis eksik satirlari UPDATE etmek kisiti tetikliyor. Uyruk
-- duzeltmesi o satirlari ATLAR - burada isimiz uyruk, veri onarimi degil.
update public.taraf_hasta
   set uyruk = '9980'
 where upper(trim(coalesce(uyruk, ''))) in ('TR', 'TC', 'TURKIYE', 'TÜRKİYE')
   and (dogum_tarihi is not null or coalesce(kimliksiz::integer, 0) = 1);

update public.taraf_personel
   set uyruk = '9980'
 where upper(trim(coalesce(uyruk, ''))) in ('TR', 'TC', 'TURKIYE', 'TÜRKİYE');

do $$
begin
    raise notice '609 tamam: % SKRS listesi, % kod degeri',
        (select count(*) from public.kod_liste where skrs_liste <> ''),
        (select count(*) from public.kod_deger d
           join public.kod_liste l on l.id = d.liste_id
          where l.skrs_liste <> '' and d.skrs_kod <> '');
end $$;
